css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .42); position: relative; }
.loader::after { content: ''; position: absolute; bottom: 16%; left: 0; width: 100%; height: 8%; border-radius: 999px; background: color-mix(in srgb, #000 18%, var(--accent-2)); }
.loader span { position: absolute; bottom: 10%; width: 14%; height: 54%; border-radius: 40% 40% 7px 7px; background: linear-gradient(var(--accent-2), color-mix(in srgb, #000 26%, var(--accent-2))); animation: handoff calc(var(--loader-speed) * 3) ease-in-out infinite; }
.loader span::after { content: ''; position: absolute; bottom: 96%; left: 14%; width: 72%; height: calc(var(--loader-size) * .075); border-radius: 50%; background: color-mix(in srgb, #fff 16%, var(--accent-2)); }
.loader span:nth-child(1) { left: 3%; }
.loader span:nth-child(2) { left: 43%; animation-delay: calc(var(--loader-speed) * .9); }
.loader span:nth-child(3) { left: 83%; animation-delay: calc(var(--loader-speed) * 1.8); }
.loader .baton { position: absolute; bottom: 40%; width: 20%; height: 13%; border-radius: 999px; background: linear-gradient(90deg, var(--accent), color-mix(in srgb, #fff 42%, var(--accent))); animation: pass calc(var(--loader-speed) * 3) ease-in-out infinite; }
@keyframes pass { 0%, 8% { left: 4%; } 30%, 38% { left: 44%; } 60%, 68% { left: 82%; } 92%, 100% { left: 4%; } }
@keyframes handoff { 0%, 14% { transform: scaleY(1); filter: brightness(1); } 22% { transform: scaleY(1.14); filter: brightness(1.4); } 34%, 100% { transform: scaleY(1); filter: brightness(1); } }
